46	bool preProcess(const string fileName, const string newFileName) {
47		printTips("开始程序预处理");
48		//定义文件流 
49		fstream fs;
50		//供读使用
51		fs.open(fileName.c_str(), ios::in);
52		//判空 
53		if (!fs) {
54			cout << "file not exsist!";
55			return false;
56		}
57		//将文件中字符串写入code字符串中
58		istreambuf_iterator<char> beg(fs), end;
59		string code(beg, end);
60		printTask("读入原程序：","-");
61		cout << endl << code << endl;
62		fs.close();
63	
64		//对缓冲字符串做去行注释的处理 
65		int idxBeg = -1;
66		int idxEnd = -1;
67		//去除单行注释
68		while ( code.find("//") != code.npos) {
69			idxBeg = code.find("//");
70			idxEnd = code.find('\n', idxBeg);
71			code.erase(idxBeg, idxEnd - idxBeg);
72		}
73		//去除多行注释
74		while (code.find("/*") != code.npos) {
75			idxBeg = code.find("/*");
76			idxEnd = code.find("*/", idxBeg);
77			code.erase(idxBeg, idxEnd - idxBeg+2);
78		}
79		//去除换行
80		while (code.find('\n') != code.npos) {
81			code.erase(code.find('\n'),1);
82		}
83		//去除制表符
84		while (code.find('\t') != code.npos) {
85			code.erase(code.find('\t'), 1);
86		}
87		//去除多余的空格
88		int flag = 0;
89		while (code.find(' ',flag) != code.npos) {
90			idxBeg = code.find(' ', flag);
91			idxEnd = code.find_first_not_of(" ", idxBeg);
92			int len = idxEnd - idxBeg - 1;
93			code.erase(idxBeg, len);
94			flag = idxEnd-len;	
95		}
96		printTask("预处理完成后代码：","-");
97		cout << endl << code << endl << endl;
98	
99		fs.open(newFileName.c_str(), ios::out);
100		fs << code.c_str();
101		fs.close();
102		printTask("预处理后代码写入文件成功","-");
103		cout << endl;
104	
105		return true;
106	}
