109	bool IsIdentifier(const string word) {
110		bool flagStatus=false;
111		if (isalpha(word[0]) || word[0] == '_') {
112			for (int i = 1; i < int(word.length()); i++) {
113				if ( !(isdigit(word[i]) || isalpha(word[i]) || word[i] == '_') ) {
114					return flagStatus;
115				}
116			}
117			flagStatus = true;
118		}
119		return flagStatus;
120	}
121	//判断单词是否是数字
122	bool IsNum(const string word) {
123		bool flagStatus = false;
124		for (int i = 1; i < word.length(); i++) {
125			if (!(isdigit(word[i]))) {
126				return flagStatus;
127			}
128		}
129		flagStatus = true;
130		return flagStatus;
131	}
