133	int wtMatch(const string word) {
134		//单词-类型映射：word-type map
135		map<string, int> wtMap;
136		map<string, int>::iterator iter;
137		wtMap["void"] = 1;
138		wtMap["main"] = 2;
139		wtMap["int"] = 3;
140		wtMap["cout"] = 4;
141		wtMap["return"] = 5;
142		wtMap["("] = 6;
143		wtMap[")"] = 7;
144		wtMap["{"] = 8;
145		wtMap["}"] = 9;
146		wtMap["<<"] = 10;
147		wtMap[";"] = 11;
148		wtMap[","] = 12;
149		wtMap["="] = 13;
150		wtMap["*"] = 14;
151		wtMap["/"] = 15;
152	
153		iter = wtMap.find(word.c_str());
154		if (iter != wtMap.end())
155			return iter->second;
156		else {
157			if (IsIdentifier(word))	return 16;
158			else if (IsNum(word)) return 17;
159			else return 18;
160		}
161	
162	}
