138	void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
139		
140		//判断接下来是否是右部
141		bool is_right = false;
142		string temp_str = "";
143		rule temp_rule;
144		for (int i = 0; i < text.size(); i++) {
145			char temp_ch = text[i];
146			//如果在左部
147			if (!is_right) {
148				//直接跳过空格和冒号
149				if (temp_ch == ' ' || temp_ch == ':') {
150					continue;
151				}
152				//遇到等于号切换左右部
153				else if (temp_ch == '=') {
154					is_right = true;
155				}
156				//遇到非空字符直接放进rule左部
157				else {
158					temp_rule.left = temp_ch;
159					non_terminal.insert(temp_ch);
160				}
161			}
162			//如果在右部
163			else {
164				//遇到空格说明rule结束，切换左右部，同时将rule放进rules
165				if (temp_ch == ' ') {
166					temp_rule.right.push_back(temp_str);
167					right_parts.insert(temp_str);
168					rules.push_back(temp_rule);
169	
170					//对rule进行重新初始化
171					temp_rule = rule();
172					temp_str = "";
173					is_right = false;
174				}
175				//如果遇到|，则将字符串放入rule右部，同时初始化字符串
176				else if (temp_ch == '|') {
177					temp_rule.right.push_back(temp_str);
178					right_parts.insert(temp_str);
179					temp_str = "";
180				}
181				//其他字符直接加在字符串后
182				else {
183					temp_str = temp_str + temp_ch;
184					if (!isupper(temp_ch))
185						terminal.insert(temp_ch);
186					if (i + 1 == text.size()) {
187						temp_rule.right.push_back(temp_str);
188						right_parts.insert(temp_str);
189						rules.push_back(temp_rule);
190					}
191				}
192			}
193		}
194	}
