230	F_set findFirst(const string ss, vector<rule> rules) {
231		F_set f_set;
232		f_set.is_first = true;
233		f_set.left = ss;
234		//bool flag = false;
235		int i = 0;
236		while( i < ss.size()) {
237			bool flag = false;
238			char temp_ch = ss[i];
239			//终结符
240			if (!isupper(temp_ch)) {
241				f_set.right.insert(temp_ch);
242				return f_set;
243			}
244			//非终结符, 如A
245			else{
246				//遍历查找左部与该大写字母相同的规则
247				for (int i = 0; i < rules.size(); i++) {
248					if (rules[i].left == temp_ch) {
249						//找到匹配的规则，如A::= xxx |xxxx
250						//遍历递归规则右部
251						for (int j = 0; j < rules[i].right.size(); j++) {
252							//xxx
253							string temp_str = rules[i].right[j];
254							//若xxx非空
255							if (temp_str[0] != '@') {
256								//继续对右部求First集
257								F_set f_set_temp = findFirst(temp_str, rules);
258								for (set<char>::iterator it = f_set_temp.right.begin(); it != f_set_temp.right.end(); it++) {
259									if (*it == '@') {
260										flag = true;
261										continue;
262									}
263									f_set.right.insert(*it);
264								}
265							}
266							//若xxx为空
267							else {
268								flag = true;
269							}
270						}
271					}
272				}
273			}
274			if (flag) {
275				if (i == ss.size() - 1)
276					f_set.right.insert('@');
277				i++;
278			}
279			else {
280				return f_set;
281			}
282		}
283		return f_set;
284	}
