361	LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules) {
362		//从终结符中提取表头
363		vector<char> table_head;
364		for (set<char>::iterator it = terminal.begin(); it != terminal.end(); it++) {
365			if (*it != '@')
366				table_head.push_back(*it);
367		}
368		table_head.push_back('#');
369	
370		//定义LL1分析表结构并初始化
371		LL_1_table table;
372		for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
373			table.row.push_back(*it);
374		}
375		for (int i = 0; i < table_head.size(); i++) {
376			table.col.push_back(table_head[i]);
377		}
378		for (int i = 0; i < table.row.size() * table.col.size(); i++) {
379			rule rule_temp;
380			rule_temp.left = ' ';
381			table.rules.push_back(rule_temp);
382		}
383	
384		//开始逐条分析规则
385		for (int i = 0; i < rules.size(); i++) {
386			//拿到规则
387			rule rule_temp = rules[i];
388			//遍历规则的不同右部
389			for (int j = 0; j < rule_temp.right.size(); j++) {
390				//拿到右部，获取右部的first集
391				set<char> first_set = findFirst(rules[i].right[j], rules).right;
392				//遍历first集
393				for (set<char>::iterator it = first_set.begin(); it != first_set.end(); it++) {
394					//如果First集中非空
395					if (*it != '@') {
396						//定位行号和列号
397						int col = distance(table.col.begin(), find(table.col.begin(), table.col.end(), *it));
398						int row = distance(table.row.begin(), find(table.row.begin(), table.row.end(), rule_temp.left));
399						//将规则左部-》当前部分右部存入表格
400						table.rules[row * table.col.size() + col].left = rule_temp.left;
401						table.rules[row * table.col.size() + col].right.push_back(rule_temp.right[j]);
402					}
403					//如果first集中有空
404					else {
405						//获取规则左部的Follow集
406						set<char> follow_set = findFollow(rules[i].left, rules).right;
407						//遍历Follow集
408						for(set<char>::iterator it_ = follow_set.begin();it_!=follow_set.end();it_++){
409							//定位行号和列号
410							int col = distance(table.col.begin(), find(table.col.begin(), table.col.end(), *it_));
411							int row = distance(table.row.begin(), find(table.row.begin(), table.row.end(), rule_temp.left));
412							//将规则左部-》当前部分右部存入表格
413							table.rules[row * table.col.size() + col].left = rule_temp.left;
414							table.rules[row * table.col.size() + col].right.push_back(rule_temp.right[j]);
415						}
416					}
417				}
418			}
419			
420		}
421		return table;
422	}
