443	void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
444		string left_str, right_str;
445		char temp_char;
446		int len_left = analysis_s.size();
447		int len_right = input_s.size();
448	
449		stack<char> temp;
450		for (int i = 0; i < len_left; i++) {
451			temp.push(analysis_s.top());
452			analysis_s.pop();
453		}
454		for (int i = 0; i < len_left; i++) {
455			temp_char = temp.top();
456			left_str = left_str + temp_char;
457			temp.pop();
458		}
459		for (int i = 0; i < len_right; i++) {
460			temp_char = input_s.top();
461			right_str = right_str + temp_char;
462			input_s.pop();
463		}
464		cout <<endl<< std::left << setw(10) << left_str << std::right << setw(10) << right_str << setw(5) <<" "<< std::left << setw(20) << rule_temp;
