466	void syntacticAnalysis(LL_1_table table) {
467		cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
468		//等待用户输入字符串以进行分析
469		string input;
470		cin >> input;
471	
472		//将该字符串放入栈中
473		stack<char> input_s;
474		input_s.push('#');
475		for (int i = input.size() - 1; i >= 0; i--) {
476			input_s.push(input[i]);
477		}
478		stack<char> analysis_s;
479		analysis_s.push('#');
480		analysis_s.push('E');
481	
482		cout << std::left << setw(10) << "分析栈" << std::right << setw(10) << "预留输入串栈" << setw(5) << "" << std::left << setw(10) << "产生式";
483		bool flag = true;
484		while (!(analysis_s.empty() && input_s.empty())) {
485			char left_ch = analysis_s.top();
486			char right_ch = input_s.top();
487			//如果左侧栈顶为非终结符
488			if (isupper(left_ch)) {
489				//到分析表中查找元素
490				int row = distance(table.row.begin(), find(table.row.begin(), table.row.end(), left_ch));
491				int col = distance(table.col.begin(), find(table.col.begin(), table.col.end(), right_ch));
492				//取出对应规则
493				rule rule_temp = table.rules[row * table.col.size() + col];
494				//如果规则非空
495				if (rule_temp.left != ' ') {
496					//输出当前状况
497					print_state(analysis_s, input_s, rule_temp);
498					//分析栈顶出栈
499					analysis_s.pop();
500					//取出规则右部进行入栈操作(右部非空情况下）
501					if (rule_temp.right[0][0] != '@') {
502						string temp_str = rule_temp.right[0];
503						for (int i = temp_str.size() - 1; i >= 0; i--) {
504							analysis_s.push(temp_str[i]);
505						}
506					}
507				}
508				else {
509					print_state(analysis_s, input_s, rule_temp);
510					flag = false;
511					break;
512				}
513			}
514			//如果左侧栈顶为终结符
515			else {
516				if (left_ch == right_ch) {
517					//输出当前状况
518					rule rule_temp;
519					rule_temp.left = ' ';
520					print_state(analysis_s, input_s, rule_temp);
521	
522					analysis_s.pop();
523					input_s.pop();
524				}
525				else {
526					bool flag = false;
527					break;
528				}
529			}
530	
531		}
532		cout<<endl << "字符串" << input;
533		if (!flag)
534			cout << "不";
535		cout << "是该文法的句子";
536	}

