	map<string, int> wtMap;
	map<string, int>::iterator iter;
	wtMap["void"] = 1;
	wtMap["main"] = 2;
	wtMap["int"] = 3;
	wtMap["cout"] = 4;
	wtMap["return"] = 5;
	wtMap["("] = 6;
	wtMap[")"] = 7;
	wtMap["{"] = 8;
	wtMap["}"] = 9;
	wtMap["<<"] = 10;
	wtMap[";"] = 11;
	wtMap[","] = 12;
	wtMap["="] = 13;
	wtMap["*"] = 14;
	wtMap["/"] = 15;

	iter = wtMap.find(word.c_str());
	if (iter != wtMap.end())
		return iter->second;
	else {
		if (IsIdentifier(word))	return 16;
		else if (IsNum(word)) return 17;
		else return 18;
	}

}

