F_set findFirst(const string ss, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = true;
	f_set.left = ss;
	//bool flag = false;
	int i = 0;
	while( i < ss.size()) {
		bool flag = false;
		char temp_ch = ss[i];
		//终结符
		if (!isupper(temp_ch)) {
			f_set.right.insert(temp_ch);
			return f_set;
		}
		//非终结符, 如A
		else{
			//遍历查找左部与该大写字母相同的规则
			for (int i = 0; i < rules.size(); i++) {
				if (rules[i].left == temp_ch) {
					//找到匹配的规则，如A::= xxx |xxxx
					//遍历递归规则右部
					for (int j = 0; j < rules[i].right.size(); j++) {
						//xxx
						string temp_str = rules[i].right[j];
						//若xxx非空
						if (temp_str[0] != '@') {
							//继续对右部求First集
							F_set f_set_temp = findFirst(temp_str, rules);
							for (set<char>::iterator it = f_set_temp.right.begin(); it != f_set_temp.right.end(); it++) {
								if (*it == '@') {
									flag = true;
									continue;
								}
								f_set.right.insert(*it);
							}
						}
						//若xxx为空
						else {
							flag = true;
						}
					}
				}
			}
		}
		if (flag) {
			if (i == ss.size() - 1)
				f_set.right.insert('@');
			i++;
		}
		else {
			return f_set;
		}
	}
	return f_set;
}

